/**
 * Client-side obfuscation for values kept in localStorage (AES-GCM via Web Crypto).
 *
 * SECURITY NOTE: this is NOT a security boundary. The key is derived from a session id that
 * sits in sessionStorage next to its salt, so any script running on this origin (for example
 * after an XSS) can re-derive the key and read the data. It only keeps values from sitting in
 * localStorage as plain text. Never store credentials, tokens, payment data or anything else
 * whose disclosure matters here; keep those on the server.
 */

const ALGORITHM = 'AES-GCM';
const KEY_LENGTH = 256;
const IV_LENGTH = 12;
const SALT_LENGTH = 16;

/**
 * Generate a cryptographic key from a password
 */
async function deriveKey(password: string, salt: Uint8Array): Promise<CryptoKey> {
  const encoder = new TextEncoder();
  const safeSalt = Uint8Array.from(salt);
  const passwordKey = await crypto.subtle.importKey(
    'raw',
    encoder.encode(password),
    'PBKDF2',
    false,
    ['deriveBits', 'deriveKey'],
  );

  return crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: safeSalt,
      iterations: 100000,
      hash: 'SHA-256',
    },
    passwordKey,
    { name: ALGORITHM, length: KEY_LENGTH },
    false,
    ['encrypt', 'decrypt'],
  );
}

const SESSION_SALT_KEY = 'wasel_session_salt';

/**
 * Get or create a stable salt for the session, then derive the encryption key.
 * The salt is persisted in sessionStorage so the same key can be re-derived for decryption.
 */
async function getSessionKeyAndSalt(): Promise<{ key: CryptoKey; salt: Uint8Array }> {
  const sessionId = sessionStorage.getItem('wasel_session_id');
  if (!sessionId) {
    throw new Error('No active session');
  }

  let salt: Uint8Array;
  const storedSalt = sessionStorage.getItem(SESSION_SALT_KEY);
  if (storedSalt) {
    salt = Uint8Array.from(atob(storedSalt), c => c.charCodeAt(0));
  } else {
    salt = crypto.getRandomValues(new Uint8Array(SALT_LENGTH));
    const saltBase64 = btoa(Array.from(salt, b => String.fromCharCode(b)).join(''));
    sessionStorage.setItem(SESSION_SALT_KEY, saltBase64);
  }

  const key = await deriveKey(sessionId, salt);
  return { key, salt };
}

/**
 * Encrypt sensitive data before storing in localStorage
 */
export async function encryptData(data: string): Promise<string> {
  try {
    const { key, salt } = await getSessionKeyAndSalt();
    const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH));
    const encoder = new TextEncoder();
    const encodedData = encoder.encode(data);

    const encryptedData = await crypto.subtle.encrypt({ name: ALGORITHM, iv }, key, encodedData);

    // Combine salt + IV + encrypted data
    const combined = new Uint8Array(salt.length + iv.length + encryptedData.byteLength);
    combined.set(salt, 0);
    combined.set(iv, salt.length);
    combined.set(new Uint8Array(encryptedData), salt.length + iv.length);

    // Convert to base64 using Array.from to avoid stack overflow on large buffers
    return btoa(Array.from(combined, b => String.fromCharCode(b)).join(''));
  } catch {
    // Encryption failed — rethrow with a safe message
    throw new Error('Failed to encrypt data');
  }
}

/**
 * Decrypt data from localStorage
 */
export async function decryptData(encryptedData: string): Promise<string> {
  try {
    // Decode from base64
    const combined = Uint8Array.from(atob(encryptedData), c => c.charCodeAt(0));

    // Extract salt, IV and encrypted data
    const salt = combined.slice(0, SALT_LENGTH);
    const iv = combined.slice(SALT_LENGTH, SALT_LENGTH + IV_LENGTH);
    const data = combined.slice(SALT_LENGTH + IV_LENGTH);

    const sessionId = sessionStorage.getItem('wasel_session_id');
    if (!sessionId) {
      throw new Error('No active session');
    }

    const key = await deriveKey(sessionId, salt);

    const decryptedData = await crypto.subtle.decrypt({ name: ALGORITHM, iv }, key, data);

    const decoder = new TextDecoder();
    return decoder.decode(decryptedData);
  } catch {
    // Decryption failed — rethrow with a safe message
    throw new Error('Failed to decrypt data');
  }
}

/**
 * Secure storage wrapper with encryption
 */
export const secureStorage = {
  async setItem(key: string, value: string): Promise<void> {
    const encrypted = await encryptData(value);
    localStorage.setItem(`secure_${key}`, encrypted);
  },

  async getItem(key: string): Promise<string | null> {
    const encrypted = localStorage.getItem(`secure_${key}`);
    if (!encrypted) {return null;}

    try {
      return await decryptData(encrypted);
    } catch {
      // If decryption fails, remove corrupted data
      localStorage.removeItem(`secure_${key}`);
      return null;
    }
  },

  removeItem(key: string): void {
    localStorage.removeItem(`secure_${key}`);
  },

  clear(): void {
    // Storage keys are exposed through key()/length, not enumerable properties.
    // Object.keys(localStorage) sees implementation fields in test shims and may
    // miss the actual stored entries in browsers as well.
    if (typeof localStorage === 'undefined') {return;}

    const keys: string[] = [];
    for (let index = 0; index < localStorage.length; index += 1) {
      const key = localStorage.key(index);
      if (key !== null) { keys.push(key); }
    }

    for (const key of keys) {
      if (key.startsWith('secure_')) {
        localStorage.removeItem(key);
      }
    }
  },
};

/**
 * Generate cryptographically secure random ID
 */
export function generateSecureId(length = 32): string {
  const array = new Uint8Array(length);
  crypto.getRandomValues(array);
  return Array.from(array, byte => byte.toString(16).padStart(2, '0')).join('');
}

/**
 * Hash sensitive data (one-way)
 */
export async function hashData(data: string): Promise<string> {
  const encoder = new TextEncoder();
  const dataBuffer = encoder.encode(data);
  const hashBuffer = await crypto.subtle.digest('SHA-256', dataBuffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Clear master encryption key (on logout)
 */
export function clearMasterKey(): void {
  sessionStorage.removeItem('wasel_session_id');
  sessionStorage.removeItem(SESSION_SALT_KEY);
  secureStorage.clear();
}
